import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();

// $ per million tokens, copied from the pricing page. Prices change: keep this in config.
const PRICE: Record<string, { input: number; write5m: number; read: number; output: number }> = {
  "claude-haiku-4-5": { input: 1, write5m: 1.25, read: 0.1, output: 5 },
  "claude-opus-5-5":  { input: 4, write5m: 5,    read: 0.2, output: 20 },
};

export function costUsd(model: string, u: Anthropic.Usage): number {
  const p = PRICE[model];
  return (
    u.input_tokens * p.input +                          // only tokens AFTER the last cache breakpoint
    (u.cache_creation_input_tokens ?? 0) * p.write5m +  // written to the cache (5-minute TTL assumed)
    (u.cache_read_input_tokens ?? 0) * p.read +         // read from the cache
    u.output_tokens * p.output
  ) / 1_000_000;
}

// Every call in the product goes through this wrapper.
export async function tracked(
  tags: { feature: string; step: string; userId: string },
  params: Anthropic.MessageCreateParamsNonStreaming,
) {
  const msg = await client.messages.create(params);
  log({
    ...tags,
    model: params.model,
    requestId: msg._request_id,
    input: msg.usage.input_tokens,
    cacheWrite: msg.usage.cache_creation_input_tokens,
    cacheRead: msg.usage.cache_read_input_tokens,
    output: msg.usage.output_tokens,
    stopReason: msg.stop_reason,
    costUsd: costUsd(params.model, msg.usage),
  });
  return msg;
}

// Bad: caching is on, but the very first characters change on every request,
// so no prefix is ever identical: every call pays for a write and never reads
await client.messages.create({
  model: "claude-opus-5-5",
  max_tokens: 1024,
  cache_control: { type: "ephemeral" }, // automatic caching
  system: "Current time: " + new Date().toISOString() + "\n\n" + LONG_INSTRUCTIONS,
  messages,
});

// Good: the static part comes first and ends with the breakpoint; the changing part goes after it
await client.messages.create({
  model: "claude-opus-5-5",
  max_tokens: 1024,
  system: [
    { type: "text", text: LONG_INSTRUCTIONS, cache_control: { type: "ephemeral" } },
    { type: "text", text: "Current time: " + new Date().toISOString() },
  ],
  messages,
});

